insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r48-lead-source-duplicates', 'Where a lead came from, and duplicate leads', 'Read the source of a lead (ChatGPT, Google and its search terms, an ad), use it in your first call, and keep one lead per person with Merge.', array['va/sales', 'va/customer-service', 'admin/leads-and-sales-claims']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r48-lead-source-duplicates'), 1, 'Where they came from', '[{"caption":"The badge on the card","say":"Every lead from the website says where the person came from. The badge on the lead card reads ChatGPT, Google search, Google Ads, Perplexity, Bing or Direct, with the first page they opened.","visual":{"kind":"list","heading":"On the card","items":["The source badge","The search terms, when we have them","First page"]}},{"caption":"The card on the lead","say":"Open the lead. The card Where they came from lists Came from, Search terms, First page they opened, Referring page and Campaign. A row we do not know is left out.","visual":{"kind":"steps","heading":"Read it","items":["Open the lead","Find Where they came from","Read the source and the first page"]}},{"caption":"Google hides the words","say":"Google does not send the words a person searched. For a Google visit the card lists the top Google searches that bring people to that first page, from Search Console.","visual":{"kind":"rule","heading":"Google","text":"You see the page''s top searches, not this person''s own words.","tone":"warn"}},{"caption":"Use it in the call","say":"Start from what they were looking for. Someone who landed on the kill switch page wants the tracker. Someone who landed on monthly rentals wants a monthly price.","visual":{"kind":"chat","lines":[{"who":"app","text":"Came from: ChatGPT. First page: /trackers/kill-switch-for-car"},{"who":"you","text":"Hi, you were looking at our kill switch. How many cars is it for?"}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r48-lead-source-duplicates'), 2, 'One person, one lead', '[{"caption":"It joins by itself","say":"A new website form from someone who already has an open lead of the same kind joins that lead by itself, when the email or the phone is the same. The new message shows under Also wrote.","visual":{"kind":"rule","heading":"Automatic","text":"Same email or phone, an open lead: one lead.","tone":"ok"}},{"caption":"Merge with one press","say":"A card that says possible duplicate: merge opens the lead with the card Possible duplicates. Press Merge. The oldest lead is kept and everything from the other moves to it.","visual":{"kind":"steps","heading":"Merge","items":["Open the lead","Check why it matches","Press Merge"]}},{"caption":"Different person","say":"Two people can share an email or a phone, like a couple or an office line. Press Different person and the pair is never suggested again.","visual":{"kind":"rule","heading":"Not the same","text":"Different person keeps them apart for good.","tone":"warn"}},{"caption":"Renter and owner stay apart","say":"A renter lead and an owner lead of the same person are two conversations. They are never merged.","visual":{"kind":"title","heading":"Two kinds","text":"A renter lead and an owner lead stay separate"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r48-lead-source-duplicates'), 1, 'Where do you see that a lead came from ChatGPT?', '["Nowhere","The badge on the lead card and the card Where they came from on the lead","Only in the audit log","In the renter''s profile"]'::jsonb, 1, 'The card badge and the lead''s own card both say it.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
